import {selectCreators,sourceA,sourceB,reconcile,money} from './demo-data.js';
const names={canvas:['fynix-canvas.png','Fynix Studio 本地创作画布，包含文本与视频节点'],script:['fynix-script.png','Fynix Studio 本地脚本创作界面'],remix:['fynix-remix.png','Fynix Studio 本地素材改编界面']};
document.querySelectorAll('[data-shot]').forEach(btn=>btn.addEventListener('click',()=>{const [file,alt]=names[btn.dataset.shot];const img=document.getElementById('fynix-shot');img.src=new URL(file,import.meta.url).href;img.alt=alt;document.getElementById('shot-link').href=img.src;document.getElementById('shot-link').setAttribute('aria-label','查看完整'+btn.textContent+'截图');document.querySelectorAll('[data-shot]').forEach(b=>b.setAttribute('aria-pressed',String(b===btn)));}));
let visibleCreators=[];
function renderCreators(){visibleCreators=selectCreators(document.getElementById('creator-query').value,Number(document.getElementById('creator-budget').value));const list=document.getElementById('creator-list');list.replaceChildren();for(const c of visibleCreators){const row=document.createElement('div');row.className='creator-row';const avatar=document.createElement('div');avatar.className='avatar';avatar.style.background=c.color;avatar.textContent=c.initial;const name=document.createElement('div');const strong=document.createElement('div');strong.className='creator-name';strong.textContent=c.name;const style=document.createElement('div');style.className='creator-style';style.textContent=c.style;name.append(strong,style);const source=document.createElement('div');source.className='creator-source';source.append(document.createTextNode(c.reason),document.createElement('br'),document.createTextNode(c.source));const price=document.createElement('div');price.className='creator-price';price.textContent='¥'+c.price.toLocaleString('en-US');row.append(avatar,name,source,price);list.append(row);}if(!visibleCreators.length){const el=document.createElement('p');el.className='empty';el.textContent='没有符合条件的候选';list.append(el);}document.getElementById('creator-count').textContent=visibleCreators.length+' 位候选';document.getElementById('export-creators').disabled=!visibleCreators.length;}
function downloadCsv(filename,rows){const escape=v=>'"'+String(v??'').replaceAll('"','""')+'"';const blob=new Blob(['\ufeff'+rows.map(r=>r.map(escape).join(',')).join('\r\n')],{type:'text/csv;charset=utf-8'});const url=URL.createObjectURL(blob);const a=document.createElement('a');a.href=url;a.download=filename;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}
const query=document.getElementById('creator-query');if(query){query.addEventListener('input',renderCreators);document.getElementById('creator-budget').addEventListener('change',renderCreators);renderCreators();document.getElementById('export-creators').addEventListener('click',()=>downloadCsv('达人候选_演示数据.csv',[['名称','内容风格','报价','依据','数据性质'],...visibleCreators.map(c=>[c.name,c.style,c.price,c.source,'虚构演示数据'])]));}
const rows=reconcile(sourceA,sourceB);let activeFilter='all';const statusText={matched:'一致',difference:'金额差异',missing:'来源 B 缺失',duplicate:'来源 B 重复'};
function renderFinance(){const body=document.getElementById('finance-rows');body.replaceChildren();for(const r of rows.filter(r=>activeFilter==='all'||r.status===activeFilter)){const tr=document.createElement('tr');for(const v of [r.id,r.aCount>1?'重复 '+r.aCount+' 笔':money(r.a),r.bCount>1?'重复 '+r.bCount+' 笔':money(r.b),money(r.delta)]){const td=document.createElement('td');td.textContent=v;tr.append(td);}const td=document.createElement('td');td.className='status '+r.status;td.textContent=statusText[r.status];tr.append(td);body.append(tr);}}
if(document.getElementById('finance-rows')){document.getElementById('issue-total').textContent=rows.filter(r=>r.status!=='matched').length+' 项待复核';renderFinance();document.querySelectorAll('[data-filter]').forEach(b=>b.addEventListener('click',()=>{activeFilter=b.dataset.filter;document.querySelectorAll('[data-filter]').forEach(x=>x.setAttribute('aria-pressed',String(x===b)));renderFinance();}));document.getElementById('export-finance').addEventListener('click',()=>downloadCsv('财务核验_演示数据.csv',[['业务编号','来源A','来源B','差额B-A','结果','数据性质'],...rows.map(r=>[r.id,money(r.a),money(r.b),money(r.delta),statusText[r.status],'虚构演示数据'])]));}
document.querySelector('[data-print]')?.addEventListener('click',()=>window.print());
